import { useEffect, useState } from "react";
import { format, parseISO } from "date-fns";
import { MailCheck, MailX } from "lucide-react";
import { toast } from "sonner";
import { api } from "@/lib/api";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const STATUSES = ["neu", "in Bearbeitung", "erledigt"];

export const InquiriesPanel = () => {
  const [items, setItems] = useState([]);
  const load = () => api.get("/admin/inquiries").then((r) => setItems(r.data));
  useEffect(() => { load(); }, []);

  const setStatus = async (id, status) => {
    await api.patch(`/admin/inquiries/${id}`, { status });
    toast.success("Status aktualisiert");
    load();
  };

  if (!items.length) return <p data-testid="inquiries-empty" className="text-muted-foreground">Noch keine Anfragen eingegangen.</p>;

  return (
    <div className="space-y-4">
      {items.map((i) => (
        <article key={i.id} data-testid={`admin-inquiry-${i.id}`} className="border border-border bg-card p-6">
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div>
              <p className="text-xs uppercase tracking-[0.2em] text-primary">{i.project_type} {i.material && `· ${i.material}`}</p>
              <h3 className="mt-1 font-display text-2xl">{i.name}</h3>
              <p className="text-sm text-muted-foreground">
                <a href={`mailto:${i.email}`} className="hover:text-primary">{i.email}</a>
                {i.phone && ` · ${i.phone}`} · {format(parseISO(i.created_at), "dd.MM.yyyy HH:mm")}
              </p>
            </div>
            <div className="flex items-center gap-3">
              <span title={i.email_sent ? "E-Mail versendet" : "E-Mail nicht versendet"}>
                {i.email_sent ? <MailCheck className="h-4 w-4 text-primary" /> : <MailX className="h-4 w-4 text-destructive" />}
              </span>
              <Select value={i.status} onValueChange={(v) => setStatus(i.id, v)}>
                <SelectTrigger className="w-40 rounded-none" data-testid={`admin-inquiry-status-${i.id}`}><SelectValue /></SelectTrigger>
                <SelectContent>{STATUSES.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent>
              </Select>
            </div>
          </div>
          <p className="mt-4 whitespace-pre-line text-sm leading-relaxed text-foreground/85">{i.message}</p>
          <p className="mt-3 text-xs text-muted-foreground">
            {i.quantity && `Menge: ${i.quantity} · `}Wunschtermin: {i.desired_date ? format(parseISO(i.desired_date), "dd.MM.yyyy") : "–"}
          </p>
        </article>
      ))}
    </div>
  );
};
