import { useMemo, useState } from "react";
import { imgSrc } from "@/lib/api";
import { SectionHead, Reveal } from "@/components/site/Reveal";

export const Portfolio = ({ products }) => {
  const cats = useMemo(() => ["Alle", ...Array.from(new Set(products.map((p) => p.category)))], [products]);
  const [cat, setCat] = useState("Alle");
  const shown = cat === "Alle" ? products : products.filter((p) => p.category === cat);

  return (
    <section id="portfolio" data-testid="portfolio-section" className="border-t border-border py-24 lg:py-32">
      <div className="mx-auto max-w-7xl px-6 lg:px-12">
        <div className="flex flex-col justify-between gap-10 lg:flex-row lg:items-end">
          <SectionHead
            eyebrow="Portfolio"
            title="Gravierte Arbeiten aus der Werkstatt"
            intro="Holz-Deko und Schilder, personalisierte Geschenke, Gravuren auf Leder, Metall oder Glas und Werbeartikel für Firmen."
            testid="portfolio-title"
          />
          <div className="flex flex-wrap gap-2" data-testid="portfolio-filters">
            {cats.map((c) => (
              <button
                key={c}
                onClick={() => setCat(c)}
                data-testid={`portfolio-filter-${c}`}
                className={`border px-4 py-2 text-xs tracking-wide transition-colors duration-200 ${
                  c === cat ? "border-primary bg-primary text-primary-foreground" : "border-border text-muted-foreground hover:border-primary hover:text-primary"
                }`}
              >
                {c}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-16 grid auto-rows-[260px] grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {shown.map((p, i) => (
            <Reveal key={p.id} delay={(i % 3) * 0.08} className={i % 5 === 0 ? "sm:row-span-2" : ""}>
              <figure data-testid={`portfolio-card-${p.id}`} className="group relative h-full overflow-hidden border border-border bg-card transition-colors duration-300 hover:border-primary">
                <img src={imgSrc(p.image)} alt={p.title} loading="lazy" className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-105" />
                <figcaption className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-background via-background/70 to-transparent p-6 pt-16">
                  <span className="text-[11px] uppercase tracking-[0.28em] text-primary">{p.material || p.category}</span>
                  <p className="mt-2 font-display text-2xl leading-tight text-foreground">{p.title}</p>
                </figcaption>
              </figure>
            </Reveal>
          ))}
        </div>
        {!shown.length && <p className="mt-12 text-muted-foreground">Noch keine Arbeiten in dieser Kategorie.</p>}
      </div>
    </section>
  );
};
