import { useEffect, useRef, useState } from "react";
import { imgSrc } from "@/lib/api";

export const Showcase = ({ products }) => {
  const items = products.slice(0, 6);
  const [active, setActive] = useState(0);
  const refs = useRef([]);

  useEffect(() => {
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) setActive(Number(e.target.dataset.index));
        });
      },
      { rootMargin: "-45% 0px -45% 0px" }
    );
    refs.current.forEach((el) => el && obs.observe(el));
    return () => obs.disconnect();
  }, [items.length]);

  if (!items.length) return null;

  return (
    <section id="werkstatt" data-testid="scroll-showcase" className="relative border-t border-border py-24 lg:py-32">
      <div className="mx-auto max-w-7xl px-6 lg:px-12">
        <p className="eyebrow">Aus der Werkstatt</p>
        <div className="mt-12 grid gap-12 lg:grid-cols-2 lg:gap-20">
          <div className="sticky top-24 z-10 h-[46vh] self-start lg:h-[72vh]">
            <div className="relative h-full w-full overflow-hidden border border-border bg-card">
              {items.map((p, i) => (
                <img
                  key={p.id}
                  src={imgSrc(p.image)}
                  alt={p.title}
                  data-testid={`showcase-image-${i}`}
                  className={`absolute inset-0 h-full w-full object-cover transition-[opacity,transform] duration-700 ${
                    i === active ? "scale-100 opacity-100" : "scale-105 opacity-0"
                  }`}
                />
              ))}
              <div key={active} className="pointer-events-none absolute inset-x-0 top-0 h-full">
                <div className="laser-line animate-laser-scan h-[2px] w-full" />
              </div>
              <div className="absolute inset-x-0 bottom-0 flex items-end justify-between bg-gradient-to-t from-background/90 to-transparent p-6">
                <span className="font-display text-5xl font-light text-foreground/90" data-testid="showcase-counter">
                  {String(active + 1).padStart(2, "0")}
                  <span className="text-lg text-muted-foreground"> / {String(items.length).padStart(2, "0")}</span>
                </span>
                <span className="text-xs uppercase tracking-[0.3em] text-primary">{items[active]?.material}</span>
              </div>
            </div>
          </div>

          <div>
            {items.map((p, i) => (
              <article
                key={p.id}
                ref={(el) => (refs.current[i] = el)}
                data-index={i}
                data-testid={`showcase-item-${i}`}
                className="flex min-h-[60vh] flex-col justify-center border-l border-border py-12 pl-8 lg:min-h-[80vh] lg:pl-12"
              >
                <span className={`text-xs uppercase tracking-[0.3em] transition-colors duration-500 ${i === active ? "text-ember" : "text-muted-foreground"}`}>
                  {p.category}
                </span>
                <h3 className={`mt-4 font-display text-4xl font-light leading-tight transition-colors duration-500 sm:text-5xl ${i === active ? "text-foreground" : "text-foreground/40"}`}>
                  {p.title}
                </h3>
                {p.description && <p className="mt-6 max-w-md text-base leading-relaxed text-muted-foreground">{p.description}</p>}
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};
