import { useEffect, useState } from "react";
import { format } from "date-fns";
import { de } from "date-fns/locale";
import { CalendarIcon, Loader2, Check } from "lucide-react";
import { toast } from "sonner";
import { Link } from "react-router-dom";
import { api, formatApiError } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";

const TYPES = ["Holz-Deko & Schilder", "Personalisierte Geschenke", "Hochzeit & Feste", "Gravur auf Leder, Metall oder Glas", "Werbeartikel für Firmen / Vereine", "Etwas anderes"];
const MATERIALS = ["Holz", "Leder", "Metall", "Glas", "Noch unsicher"];
const EMPTY = { name: "", email: "", phone: "", project_type: "", material: "", quantity: "", message: "" };
const field = "rounded-none border-border bg-background/60 h-12 focus-visible:ring-primary";

const Field = ({ label, id, children }) => (
  <div className="space-y-2">
    <Label htmlFor={id} className="text-xs uppercase tracking-[0.2em] text-muted-foreground">{label}</Label>
    {children}
  </div>
);

export const InquiryForm = () => {
  const [f, setF] = useState(EMPTY);
  const [date, setDate] = useState();
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  useEffect(() => {
    const on = (e) => {
      setDone(false);
      setF((prev) => ({ ...prev, project_type: e.detail }));
    };
    window.addEventListener("preset-inquiry", on);
    return () => window.removeEventListener("preset-inquiry", on);
  }, []);
  const set = (k) => (e) => setF({ ...f, [k]: e?.target ? e.target.value : e });

  const submit = async (e) => {
    e.preventDefault();
    if (!f.project_type) return toast.error("Bitte wähle eine Projektart.");
    if (f.message.trim().length < 10) return toast.error("Bitte beschreibe dein Projekt in ein paar Sätzen.");
    setBusy(true);
    try {
      await api.post("/inquiries", { ...f, desired_date: date ? format(date, "yyyy-MM-dd") : null });
      setDone(true);
      setF(EMPTY);
      setDate(undefined);
      toast.success("Danke! Deine Anfrage ist angekommen.");
    } catch (err) {
      toast.error(formatApiError(err));
    } finally {
      setBusy(false);
    }
  };

  if (done)
    return (
      <div data-testid="inquiry-success" className="border border-primary/40 bg-card p-10">
        <Check className="h-8 w-8 text-primary" />
        <h3 className="mt-6 font-display text-4xl text-foreground">Danke für deine Anfrage!</h3>
        <p className="mt-4 text-muted-foreground">Ich melde mich persönlich bei dir, um alle Details zu besprechen.</p>
        <button data-testid="inquiry-new-button" onClick={() => setDone(false)} className="mt-8 text-sm text-primary underline-offset-4 hover:underline">
          Weitere Anfrage senden
        </button>
      </div>
    );

  return (
    <form onSubmit={submit} data-testid="inquiry-form" className="grid gap-6 border border-border bg-card p-6 sm:grid-cols-2 sm:p-10">
      <Field label="Name *" id="name">
        <Input id="name" required minLength={2} value={f.name} onChange={set("name")} className={field} data-testid="inquiry-name-input" />
      </Field>
      <Field label="E-Mail *" id="email">
        <Input id="email" type="email" required value={f.email} onChange={set("email")} className={field} data-testid="inquiry-email-input" />
      </Field>
      <Field label="Telefon (optional)" id="phone">
        <Input id="phone" value={f.phone} onChange={set("phone")} className={field} data-testid="inquiry-phone-input" />
      </Field>
      <Field label="Projektart *" id="type">
        <Select value={f.project_type} onValueChange={set("project_type")}>
          <SelectTrigger id="type" className={field} data-testid="inquiry-type-select"><SelectValue placeholder="Bitte wählen" /></SelectTrigger>
          <SelectContent>{TYPES.map((t) => <SelectItem key={t} value={t} data-testid={`inquiry-type-option-${t}`}>{t}</SelectItem>)}</SelectContent>
        </Select>
      </Field>
      <Field label="Material" id="material">
        <Select value={f.material} onValueChange={set("material")}>
          <SelectTrigger id="material" className={field} data-testid="inquiry-material-select"><SelectValue placeholder="Bitte wählen" /></SelectTrigger>
          <SelectContent>{MATERIALS.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}</SelectContent>
        </Select>
      </Field>
      <div className="grid grid-cols-2 gap-4">
        <Field label="Menge" id="qty">
          <Input id="qty" placeholder="z. B. 25" value={f.quantity} onChange={set("quantity")} className={field} data-testid="inquiry-quantity-input" />
        </Field>
        <Field label="Wunschtermin" id="date">
          <Popover>
            <PopoverTrigger asChild>
              <button type="button" id="date" data-testid="inquiry-date-button" className={`${field} flex w-full items-center justify-between border px-3 text-left text-sm`}>
                <span className={date ? "text-foreground" : "text-muted-foreground"}>{date ? format(date, "dd.MM.yyyy") : "Datum"}</span>
                <CalendarIcon className="h-4 w-4 text-muted-foreground" />
              </button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="end">
              <Calendar mode="single" selected={date} onSelect={setDate} locale={de} disabled={{ before: new Date() }} initialFocus />
            </PopoverContent>
          </Popover>
        </Field>
      </div>
      <div className="sm:col-span-2">
        <Field label="Deine Idee *" id="message">
          <Textarea id="message" required rows={6} value={f.message} onChange={set("message")} placeholder="Was soll graviert werden? Gibt es einen Anlass, Maße oder ein Motiv?" className="rounded-none border-border bg-background/60 focus-visible:ring-primary" data-testid="inquiry-message-input" />
        </Field>
      </div>
      <div className="flex flex-col gap-4 sm:col-span-2 sm:flex-row sm:items-center sm:justify-between">
        <p className="max-w-sm text-xs leading-relaxed text-muted-foreground">Ich antworte dir persönlich per E-Mail. Deine Angaben nutze ich nur zur Bearbeitung deiner Anfrage – mehr dazu in der <Link to="/datenschutz" data-testid="inquiry-privacy-link" className="text-primary hover:underline">Datenschutzerklärung</Link>.</p>
        <button type="submit" disabled={busy} data-testid="inquiry-submit-button" className="flex items-center justify-center gap-2 gold-bg px-10 py-4 font-brand text-sm tracking-[0.12em] disabled:opacity-60">
          {busy && <Loader2 className="h-4 w-4 animate-spin" />} Anfrage senden
        </button>
      </div>
    </form>
  );
};
