import { useEffect, useState } from "react";
import { Menu, Instagram, LockKeyhole } from "lucide-react";
import { Link } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { INSTAGRAM_URL, WhatsAppButton } from "@/components/site/Social";
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from "@/components/ui/sheet";

export const NAV = [
  { id: "portfolio", label: "Portfolio" },
  { id: "ueber-mich", label: "Über mich" },
  { id: "materialien", label: "Materialien" },
  { id: "anfrage", label: "Projekt Anfragen" },
];

export const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const { user } = useAuth();
  const adminLabel = user ? "Atelier" : "Admin-Login";
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 40);
    on();
    window.addEventListener("scroll", on, { passive: true });
    return () => window.removeEventListener("scroll", on);
  }, []);

  return (
    <header
      data-testid="site-navbar"
      className={`fixed inset-x-0 top-0 z-50 border-b transition-colors duration-300 ${
        scrolled ? "bg-background/85 backdrop-blur-md border-border" : "bg-background/30 backdrop-blur-sm border-transparent"
      }`}
    >
      <nav className="mx-auto flex h-20 max-w-7xl items-center justify-between px-6 lg:px-12">
        <a href="#top" data-testid="nav-logo" className="group flex items-center gap-3">
          <img src="/logo-mark.webp" alt="Kreativreich Logo" className="h-10 w-auto transition-transform duration-300 group-hover:scale-105" />
          <span className="gold-text font-brand text-2xl tracking-wide">Kreativreich</span>
        </a>
        <ul className="hidden items-center gap-8 whitespace-nowrap lg:flex xl:gap-10">
          {NAV.map((n) => (
            <li key={n.id}>
              <a
                href={`#${n.id}`}
                data-testid={`nav-link-${n.id}`}
                className={`relative text-sm tracking-wide transition-colors duration-200 hover:text-primary ${
                  n.id === "anfrage" ? "gold-bg px-5 py-2.5 font-medium hover:text-primary-foreground" : "text-foreground/80"
                }`}
              >
                {n.label}
              </a>
            </li>
          ))}
          <li>
            <a href={INSTAGRAM_URL} target="_blank" rel="noopener noreferrer" data-testid="nav-instagram-link" aria-label="Instagram" className="text-foreground/70 transition-colors hover:text-primary">
              <Instagram className="h-5 w-5" strokeWidth={1.5} />
            </a>
          </li>
          <li>
            <Link to="/admin" data-testid="nav-admin-link" title={adminLabel} className="flex items-center gap-2 text-xs uppercase tracking-[0.2em] text-foreground/70 transition-colors hover:text-primary">
              <LockKeyhole className="h-4 w-4" strokeWidth={1.5} /> {adminLabel}
            </Link>
          </li>
        </ul>
        <Sheet open={open} onOpenChange={setOpen}>
          <SheetTrigger asChild>
            <button data-testid="nav-mobile-toggle" className="lg:hidden p-2 text-foreground" aria-label="Menü öffnen">
              <Menu className="h-6 w-6" />
            </button>
          </SheetTrigger>
          <SheetContent side="right" className="bg-background border-border">
            <SheetTitle className="flex items-center gap-3 font-brand text-2xl">
              <img src="/logo-mark.webp" alt="" className="h-9 w-auto" />
              <span className="gold-text">Kreativreich</span>
            </SheetTitle>
            <ul className="mt-10 space-y-6">
              {NAV.map((n) => (
                <li key={n.id}>
                  <a
                    href={`#${n.id}`}
                    onClick={() => setOpen(false)}
                    data-testid={`nav-mobile-link-${n.id}`}
                    className="font-display text-3xl text-foreground transition-colors hover:text-primary"
                  >
                    {n.label}
                  </a>
                </li>
              ))}
            </ul>
            <div className="mt-12 space-y-5">
              <WhatsAppButton testid="nav-mobile-whatsapp" className="w-full" />
              <a href={INSTAGRAM_URL} target="_blank" rel="noopener noreferrer" data-testid="nav-mobile-instagram" className="flex items-center gap-2 text-sm text-foreground/80 hover:text-primary">
                <Instagram className="h-4 w-4" strokeWidth={1.5} /> @joergs_kreativreich
              </a>
              <Link to="/admin" data-testid="nav-mobile-admin-link" className="flex items-center gap-2 border-t border-border pt-5 text-sm text-foreground/80 hover:text-primary">
                <LockKeyhole className="h-4 w-4" strokeWidth={1.5} /> {adminLabel}
              </Link>
            </div>
          </SheetContent>
        </Sheet>
      </nav>
    </header>
  );
};
