import { motion } from "framer-motion";

export const Reveal = ({ children, delay = 0, className = "" }) => (
  <motion.div
    initial={{ opacity: 0, y: 18 }}
    whileInView={{ opacity: 1, y: 0 }}
    viewport={{ once: true, margin: "-60px" }}
    transition={{ duration: 0.7, delay, ease: [0.2, 0.7, 0.2, 1] }}
    className={className}
  >
    {children}
  </motion.div>
);

export const SectionHead = ({ eyebrow, title, intro, testid }) => (
  <Reveal className="max-w-2xl">
    <div className="flex items-center gap-3">
      <span className="h-1.5 w-1.5 rotate-45 bg-primary" aria-hidden="true" />
      <p className="eyebrow">{eyebrow}</p>
      <span className="h-px w-16 bg-gradient-to-r from-primary/70 to-transparent" aria-hidden="true" />
    </div>
    <h2 data-testid={testid} className="mt-5 font-display text-4xl font-light leading-[1.05] text-foreground sm:text-5xl">
      {title}
    </h2>
    {intro && <p className="mt-6 text-base leading-relaxed text-muted-foreground md:text-lg">{intro}</p>}
  </Reveal>
);
