import { CalendarDays, MapPin, Clock } from "lucide-react";
import { format, parseISO } from "date-fns";
import { de } from "date-fns/locale";
import { SectionHead, Reveal } from "@/components/site/Reveal";

export const Markets = ({ markets }) => (
  <section id="maerkte" data-testid="markets-section" className="border-t border-border py-24 lg:py-32">
    <div className="mx-auto grid max-w-7xl gap-14 px-6 lg:grid-cols-12 lg:px-12">
      <div className="lg:col-span-4">
        <SectionHead
          eyebrow="Kommende Märkte"
          title="Komm vorbei und such dir dein Unikat aus"
          intro="Versand in ganz Europa, Abholung vor Ort – oder persönlich auf einem der nächsten Märkte."
          testid="markets-title"
        />
      </div>
      <div className="lg:col-span-8">
        {markets.length === 0 ? (
          <p data-testid="markets-empty" className="border border-dashed border-border p-10 text-muted-foreground">
            Aktuell sind keine Markttermine eingetragen. Neue Termine erscheinen hier, sobald sie feststehen.
          </p>
        ) : (
          <ul className="divide-y divide-border border-y border-border">
            {markets.map((m, i) => {
              const d = parseISO(m.date);
              return (
                <Reveal key={m.id} delay={i * 0.05}>
                  <li data-testid={`market-item-${m.id}`} className="group grid grid-cols-[88px_1fr] gap-6 py-8 sm:grid-cols-[120px_1fr]">
                    <div className="border-r border-border pr-6">
                      <p className="gold-text font-display text-5xl font-light leading-none">{format(d, "dd")}</p>
                      <p className="mt-2 text-xs uppercase tracking-[0.25em] text-muted-foreground">{format(d, "MMM yyyy", { locale: de })}</p>
                    </div>
                    <div>
                      <h3 className="font-display text-3xl text-foreground transition-colors group-hover:text-primary">{m.name}</h3>
                      <div className="mt-3 flex flex-wrap gap-x-6 gap-y-2 text-sm text-muted-foreground">
                        <span className="flex items-center gap-2"><CalendarDays className="h-4 w-4" />{format(d, "EEEE, d. MMMM yyyy", { locale: de })}</span>
                        {m.time && <span className="flex items-center gap-2"><Clock className="h-4 w-4" />{m.time}</span>}
                        <span className="flex items-center gap-2"><MapPin className="h-4 w-4" />{m.location}</span>
                      </div>
                      {m.description && <p className="mt-4 max-w-xl text-sm leading-relaxed text-muted-foreground">{m.description}</p>}
                    </div>
                  </li>
                </Reveal>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  </section>
);
