import { useEffect, useState } from "react";
import { format, parseISO } from "date-fns";
import { de } from "date-fns/locale";
import { CalendarIcon, Pencil, Trash2, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { api, formatApiError } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";

const EMPTY = { name: "", time: "", location: "", description: "" };

export const MarketsPanel = () => {
  const [items, setItems] = useState([]);
  const [f, setF] = useState(EMPTY);
  const [date, setDate] = useState();
  const [editId, setEditId] = useState(null);
  const [busy, setBusy] = useState(false);
  const today = format(new Date(), "yyyy-MM-dd");

  const load = () => api.get("/admin/markets").then((r) => setItems(r.data));
  useEffect(() => { load(); }, []);

  const reset = () => { setF(EMPTY); setDate(undefined); setEditId(null); };

  const submit = async (e) => {
    e.preventDefault();
    if (!date) return toast.error("Bitte ein Datum wählen.");
    setBusy(true);
    const body = { ...f, date: format(date, "yyyy-MM-dd") };
    try {
      if (editId) await api.put(`/markets/${editId}`, body);
      else await api.post("/markets", body);
      toast.success(editId ? "Markt aktualisiert" : "Markt eingetragen");
      reset();
      load();
    } catch (err) {
      toast.error(formatApiError(err));
    } finally {
      setBusy(false);
    }
  };

  const edit = (m) => {
    setEditId(m.id);
    setF({ name: m.name, time: m.time, location: m.location, description: m.description });
    setDate(parseISO(m.date));
  };

  const remove = async (id) => {
    await api.delete(`/markets/${id}`);
    toast.success("Markt gelöscht");
    if (editId === id) reset();
    load();
  };

  return (
    <div className="grid gap-10 lg:grid-cols-[380px_1fr]">
      <form onSubmit={submit} data-testid="market-form" className="h-fit space-y-5 border border-border bg-card p-6">
        <h2 className="font-display text-2xl">{editId ? "Markt bearbeiten" : "Neuer Markttermin"}</h2>
        <div className="space-y-2">
          <Label>Name des Marktes</Label>
          <Input required value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} className="rounded-none" data-testid="market-name-input" />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-2">
            <Label>Datum</Label>
            <Popover>
              <PopoverTrigger asChild>
                <button type="button" data-testid="market-date-button" className="flex h-10 w-full items-center justify-between border border-input bg-background px-3 text-sm">
                  <span className={date ? "" : "text-muted-foreground"}>{date ? format(date, "dd.MM.yyyy") : "Wählen"}</span>
                  <CalendarIcon className="h-4 w-4 text-muted-foreground" />
                </button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar mode="single" selected={date} onSelect={setDate} locale={de} initialFocus />
              </PopoverContent>
            </Popover>
          </div>
          <div className="space-y-2">
            <Label>Uhrzeit</Label>
            <Input placeholder="10–18 Uhr" value={f.time} onChange={(e) => setF({ ...f, time: e.target.value })} className="rounded-none" data-testid="market-time-input" />
          </div>
        </div>
        <div className="space-y-2">
          <Label>Ort</Label>
          <Input required value={f.location} onChange={(e) => setF({ ...f, location: e.target.value })} className="rounded-none" data-testid="market-location-input" />
        </div>
        <div className="space-y-2">
          <Label>Info (optional)</Label>
          <Textarea rows={3} value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })} className="rounded-none" data-testid="market-description-input" />
        </div>
        <div className="flex gap-3">
          <button type="submit" disabled={busy} data-testid="market-submit-button" className="flex flex-1 items-center justify-center gap-2 gold-bg py-3 text-sm font-medium disabled:opacity-60">
            {busy && <Loader2 className="h-4 w-4 animate-spin" />} {editId ? "Speichern" : "Eintragen"}
          </button>
          {editId && <button type="button" onClick={reset} data-testid="market-cancel-edit" className="border border-border px-4 text-sm">Abbrechen</button>}
        </div>
      </form>

      <ul className="divide-y divide-border border-y border-border">
        {items.length === 0 && <li className="py-8 text-muted-foreground">Noch keine Märkte eingetragen.</li>}
        {items.map((m) => (
          <li key={m.id} data-testid={`admin-market-${m.id}`} className={`flex items-start justify-between gap-4 py-5 ${m.date < today ? "opacity-50" : ""}`}>
            <div>
              <p className="text-xs uppercase tracking-[0.2em] text-primary">
                {format(parseISO(m.date), "EEE, dd.MM.yyyy", { locale: de })} {m.time && `· ${m.time}`} {m.date < today && "· vergangen"}
              </p>
              <p className="mt-1 font-display text-2xl">{m.name}</p>
              <p className="text-sm text-muted-foreground">{m.location}</p>
            </div>
            <div className="flex gap-2">
              <button onClick={() => edit(m)} data-testid={`admin-market-edit-${m.id}`} className="p-2 text-muted-foreground transition-colors hover:text-primary" aria-label="Bearbeiten"><Pencil className="h-4 w-4" /></button>
              <button onClick={() => remove(m.id)} data-testid={`admin-market-delete-${m.id}`} className="p-2 text-muted-foreground transition-colors hover:text-destructive" aria-label="Löschen"><Trash2 className="h-4 w-4" /></button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};
