import { useEffect, useRef, useState } from "react";
import { Loader2, Trash2, Upload } from "lucide-react";
import { toast } from "sonner";
import { api, imgSrc, formatApiError } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

const MATERIALS = ["Holz", "Leder", "Metall", "Glas"];
const EMPTY = { title: "", category: "", material: "Holz", description: "" };

export const ProductsPanel = () => {
  const [items, setItems] = useState([]);
  const [cats, setCats] = useState([]);
  const [f, setF] = useState(EMPTY);
  const [file, setFile] = useState(null);
  const [busy, setBusy] = useState(false);
  const fileRef = useRef();

  const load = () => api.get("/products").then((r) => setItems(r.data));
  useEffect(() => {
    load();
    api.get("/categories").then((r) => setCats(r.data));
  }, []);

  const submit = async (e) => {
    e.preventDefault();
    if (!file) return toast.error("Bitte ein Bild auswählen.");
    if (!f.category) return toast.error("Bitte eine Kategorie wählen.");
    const fd = new FormData();
    Object.entries(f).forEach(([k, v]) => fd.append(k, v));
    fd.append("file", file);
    setBusy(true);
    try {
      await api.post("/products", fd);
      toast.success("Produkt hochgeladen");
      setF(EMPTY);
      setFile(null);
      fileRef.current.value = "";
      load();
    } catch (err) {
      toast.error(formatApiError(err));
    } finally {
      setBusy(false);
    }
  };

  const remove = async (id) => {
    await api.delete(`/products/${id}`);
    toast.success("Produkt entfernt");
    load();
  };

  return (
    <div className="grid gap-10 lg:grid-cols-[380px_1fr]">
      <form onSubmit={submit} data-testid="product-upload-form" className="h-fit space-y-5 border border-border bg-card p-6">
        <h2 className="font-display text-2xl">Neues Produktbild</h2>
        <div className="space-y-2">
          <Label>Bild (JPG, PNG, WEBP – max. 10 MB)</Label>
          <Input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setFile(e.target.files[0])} className="rounded-none" data-testid="product-file-input" />
          {file && <img src={URL.createObjectURL(file)} alt="Vorschau" className="mt-2 aspect-video w-full object-cover" />}
        </div>
        <div className="space-y-2">
          <Label>Titel</Label>
          <Input required value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} className="rounded-none" data-testid="product-title-input" />
        </div>
        <div className="space-y-2">
          <Label>Kategorie</Label>
          <Select value={f.category} onValueChange={(v) => setF({ ...f, category: v })}>
            <SelectTrigger className="rounded-none" data-testid="product-category-select"><SelectValue placeholder="Bitte wählen" /></SelectTrigger>
            <SelectContent>{cats.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Material</Label>
          <Select value={f.material} onValueChange={(v) => setF({ ...f, material: v })}>
            <SelectTrigger className="rounded-none" data-testid="product-material-select"><SelectValue /></SelectTrigger>
            <SelectContent>{MATERIALS.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>Beschreibung</Label>
          <Textarea rows={3} value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })} className="rounded-none" data-testid="product-description-input" />
        </div>
        <button type="submit" disabled={busy} data-testid="product-upload-submit" className="flex w-full items-center justify-center gap-2 gold-bg py-3 text-sm font-medium disabled:opacity-60">
          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />} Hochladen
        </button>
      </form>

      <div>
        <p className="mb-4 text-sm text-muted-foreground">{items.length} Produkte · Die neuesten erscheinen zuerst im Scroll-Showcase.</p>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {items.map((p) => (
            <div key={p.id} data-testid={`admin-product-${p.id}`} className="group relative border border-border bg-card">
              <img src={imgSrc(p.image)} alt={p.title} className="aspect-square w-full object-cover" />
              <div className="p-4">
                <p className="text-[11px] uppercase tracking-[0.2em] text-primary">{p.category}</p>
                <p className="mt-1 font-display text-xl leading-tight">{p.title}</p>
                {p.is_sample && <span className="mt-2 inline-block border border-dashed border-muted-foreground/50 px-2 py-0.5 text-[10px] text-muted-foreground">Beispielbild</span>}
              </div>
              <AlertDialog>
                <AlertDialogTrigger asChild>
                  <button data-testid={`admin-product-delete-${p.id}`} className="absolute right-2 top-2 bg-background/80 p-2 text-muted-foreground backdrop-blur transition-colors hover:text-destructive" aria-label="Löschen">
                    <Trash2 className="h-4 w-4" />
                  </button>
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Produkt löschen?</AlertDialogTitle>
                    <AlertDialogDescription>„{p.title}“ wird von der Seite entfernt.</AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Abbrechen</AlertDialogCancel>
                    <AlertDialogAction data-testid="confirm-delete-product" onClick={() => remove(p.id)}>Löschen</AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};
