import { useState } from "react";
import { Navigate, useNavigate, Link } from "react-router-dom";
import { Loader2 } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import { formatApiError } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function AdminLogin() {
  const { user, login } = useAuth();
  const nav = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  if (user) return <Navigate to="/admin" replace />;

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      await login(email, password);
      nav("/admin");
    } catch (err) {
      setError(formatApiError(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="grain relative grid min-h-screen place-items-center px-6">
      <form onSubmit={submit} data-testid="admin-login-form" className="relative w-full max-w-sm border border-border bg-card p-10">
        <Link to="/" className="block"><img src="/logo-full.webp" alt="Kreativreich" className="gold-glow mx-auto w-40" /></Link>
        <p className="eyebrow mt-4 text-center">Atelier-Login</p>
        <div className="mt-10 space-y-5">
          <div className="space-y-2">
            <Label htmlFor="email">E-Mail</Label>
            <Input id="email" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} className="h-12 rounded-none" data-testid="admin-login-email-input" />
          </div>
          <div className="space-y-2">
            <Label htmlFor="pw">Passwort</Label>
            <Input id="pw" type="password" required value={password} onChange={(e) => setPassword(e.target.value)} className="h-12 rounded-none" data-testid="admin-login-password-input" />
          </div>
          {error && <p data-testid="admin-login-error" className="text-sm text-destructive">{error}</p>}
          <button type="submit" disabled={busy} data-testid="admin-login-submit-button" className="flex w-full items-center justify-center gap-2 gold-bg py-3.5 text-sm font-medium disabled:opacity-60">
            {busy && <Loader2 className="h-4 w-4 animate-spin" />} Anmelden
          </button>
        </div>
      </form>
    </div>
  );
}
