import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Truck, Store, MapPin } from "lucide-react";
import { api } from "@/lib/api";
import { Navbar } from "@/components/site/Navbar";
import { Hero } from "@/components/site/Hero";
import { Showcase } from "@/components/site/Showcase";
import { Portfolio } from "@/components/site/Portfolio";
import { About } from "@/components/site/About";
import { Wedding } from "@/components/site/Wedding";
import { Materials } from "@/components/site/Materials";
import { Markets } from "@/components/site/Markets";
import { InquiryForm } from "@/components/site/InquiryForm";
import { SectionHead } from "@/components/site/Reveal";
import { InstagramLink, WhatsAppButton, WhatsAppFloat } from "@/components/site/Social";

const REACH = [
  { icon: Truck, label: "Versand in ganz Europa" },
  { icon: Store, label: "Abholung vor Ort" },
  { icon: MapPin, label: "Auf Märkten" },
];

const Footer = () => (
  <footer data-testid="site-footer" className="border-t border-border pb-28 pt-12 md:pb-12">
    <div className="mx-auto flex max-w-7xl flex-col gap-6 px-6 text-sm text-muted-foreground md:flex-row md:items-center md:justify-between lg:px-12">
      <p className="flex items-center gap-3"><img src="/logo-mark.webp" alt="" className="h-8 w-auto" /><span className="gold-text font-brand text-xl">Kreativreich</span><span>· Lasergravur auf Holz · Handgefertigt</span></p>
      <div className="flex flex-wrap gap-6">
        <InstagramLink testid="footer-instagram-link" />
        <a href="mailto:info@kreativreich.eu" data-testid="footer-email-link" className="transition-colors hover:text-primary">info@kreativreich.eu</a>
        <Link to="/impressum" data-testid="footer-impressum-link" className="transition-colors hover:text-primary">Impressum</Link>
        <Link to="/datenschutz" data-testid="footer-datenschutz-link" className="transition-colors hover:text-primary">Datenschutz</Link>
        <Link to="/admin" data-testid="footer-admin-link" className="transition-colors hover:text-primary">Admin-Login</Link>
      </div>
    </div>
  </footer>
);

export default function Home() {
  const [products, setProducts] = useState([]);
  const [markets, setMarkets] = useState([]);

  useEffect(() => {
    api.get("/products").then((r) => setProducts(r.data)).catch(() => {});
    api.get("/markets").then((r) => setMarkets(r.data)).catch(() => {});
  }, []);

  return (
    <div className="min-h-screen bg-background">
      <Navbar />
      <main>
        <Hero />
        <Showcase products={products} />
        <Portfolio products={products} />
        <Wedding />
        <About />
        <Materials />
        <Markets markets={markets} />
        <section id="anfrage" data-testid="inquiry-section" className="border-t border-border py-24 lg:py-32">
          <div className="mx-auto grid max-w-7xl gap-14 px-6 lg:grid-cols-12 lg:px-12">
            <div className="lg:col-span-4">
              <SectionHead
                eyebrow="Projekt Anfragen"
                title="Erzähl mir von deiner Idee"
                intro="Ob Hochzeit, Geschenk oder Werbeartikel für deine Firma oder deinen Verein – ich berate dich persönlich von Anfang bis Ende."
                testid="inquiry-title"
              />
              <ul className="mt-10 space-y-4">
                {REACH.map((r) => (
                  <li key={r.label} className="flex items-center gap-3 text-sm text-foreground/80">
                    <r.icon className="h-4 w-4 text-primary" strokeWidth={1.5} /> {r.label}
                  </li>
                ))}
              </ul>
              <div className="mt-10 border-t border-border pt-8">
                <p className="text-sm text-muted-foreground">Lieber direkt schreiben?</p>
                <WhatsAppButton testid="inquiry-whatsapp-button" className="mt-4 w-full sm:w-auto" />
                <InstagramLink testid="inquiry-instagram-link" label="@joergs_kreativreich" className="mt-5 text-sm text-foreground/80" />
              </div>
            </div>
            <div className="lg:col-span-8"><InquiryForm /></div>
          </div>
        </section>
      </main>
      <Footer />
      <WhatsAppFloat />
    </div>
  );
}
